import sys,random,time
sys.path.insert(0,'/workspace/submission');sys.path.insert(0,'/workspace/tmp')
from compiler import compile_plan
from test_compiler import check

def run(kind,seed,k=32):
 random.seed(seed); n=48
 C=list(range(k))
 parts=[[v,random.randint(0,10**12)] for v in C]
 D=sum(r for v,r in parts)
 edges=[]; caps=[]; p=1000000
 def add(u,v,amount):
  if u==v or (u,v) in edges or (v,u) in edges: return
  edges.append((u,v));caps.append((amount+p-1)//p)
 if kind=='star':
  for v,r in parts: add(v,k,D-r)
 elif kind=='bipartite':
  # use multiple rails, with slightly different rates
  for v,r in parts:
   for rail in range(4): add(v,k+rail, (D-r)//4 + random.randint(0,10**8))
 elif kind=='clos':
  for v,r in parts:
   add(v,k+v//4,D-r)
  for leaf in range(8):
   for core in range(8): add(k+leaf,k+8+core,D)
 elif kind=='chain':
  # Closely packed pendant vertices with numerous degree-2 switches
  for i in range(k-1): add(i,i+1,D)
  for w in range(k,n):
   a,b=random.sample(C,2);add(a,w,D);add(w,b,D)
 else:
  raise ValueError
 env=[[i,c] for i,c in enumerate(caps)]
 start=time.monotonic();plan,cut=compile_plan(n,edges,parts,env,p)
 check(n,edges,parts,env,p,plan,cut)
 print(kind,seed,'time',round(time.monotonic()-start,3),'size',[len(plan[q]) for q in ('trees','routes','recipes')] if plan else 'cut',flush=True)
for kind in ['star','bipartite','clos','chain']:
 for seed in range(3):run(kind,seed)
PY
